function kNearest(arr: number[], k: number, x: number): number[] {
  const byDistance = [...arr].sort((a, b) => Math.abs(a - x) - Math.abs(b - x) || a - b);
  return byDistance.slice(0, k).sort((a, b) => a - b);
}

