function kNearest(arr: number[], k: number, x: number): number[] {
  let lo = 0, hi = arr.length - 1;
  while (hi - lo + 1 > k) {
    if (x - arr[lo] > arr[hi] - x) lo++;
    else hi--;
  }
  return arr.slice(lo, hi + 1);
}

