function kNearest(arr: number[], k: number, x: number): number[] {
  let lo = 0, hi = arr.length - k;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    // the windows at mid and mid + 1 differ only in arr[mid] vs arr[mid + k]
    if (x - arr[mid] > arr[mid + k] - x) lo = mid + 1;
    else hi = mid;
  }
  return arr.slice(lo, lo + k);
}

